import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine()!!.trim().toInt()
    val s = br.readLine()!!.trim()
    val m = s.length

    val pi = IntArray(m + 1)
    var k = 0
    for (i in 1 until m) {
        while (k > 0 && s[i] != s[k]) k = pi[k]
        if (s[i] == s[k]) k++
        pi[i + 1] = k
    }

    val aut = Array(m + 1) { IntArray(2) }
    for (a in 0..m) {
        for (c in 0..1) {
            val ch = ('0' + c)
            if (a < m && s[a] == ch) {
                aut[a][c] = a + 1
            } else {
                aut[a][c] = if (a == 0) 0 else aut[pi[a]][c]
            }
        }
    }

    val sz = m + 1
    var ans = 0L
    for (r in 0..m) {
        var dp = Array(sz) { Array(sz) { LongArray(2) } }
        dp[0][r][0] = 1L
        repeat(n) {
            val nd = Array(sz) { Array(sz) { LongArray(2) } }
            for (a in 0 until sz) {
                for (b in 0 until sz) {
                    for (f in 0..1) {
                        val v = dp[a][b][f]
                        if (v == 0L) continue
                        for (c in 0..1) {
                            val na = aut[a][c]
                            val nb = aut[b][c]
                            val nf = if (f == 1 || na == m || nb == m) 1 else 0
                            nd[na][nb][nf] += v
                        }
                    }
                }
            }
            dp = nd
        }
        for (b in 0 until sz) ans += dp[r][b][1]
    }
    println(ans)
}
